import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';


export type FleetCrossoutProps = Record<string, any>;

const FleetCrossout: React.FC<FleetCrossoutProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 2,
  truckPrimaryColor = "#2C3E50",
  truckDetailColor = "#ECF0F1",
  xMarkColor = "#E74C3C",
  xMarkIndices = [1, 3],
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const sortedXIndices = [...xMarkIndices].sort((a, b) => a - b);
  const trucks = [0, 1, 2, 3, 4];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "row",
        justifyContent: "center",
        alignItems: "center",
        gap: "2%",
        padding: "0 2%",
      }}
    >
      {trucks.map((index) => {
        // 0.0s - 0.6s: Rapid pop-in from left to right
        const popInStart = index * (fps * 0.06);
        const scale = spring({
          frame: frame - popInStart,
          fps,
          config: {
            damping: 12,
            stiffness: 200,
            mass: 1,
          },
        });

        // 0.6s - 1.0s: Light shake/wobble in place
        const shakePhaseStart = fps * 0.6;
        const shakePhaseEnd = fps * 1.0;
        const shakeEnvelope = interpolate(
          frame,
          [
            shakePhaseStart,
            shakePhaseStart + fps * 0.05,
            shakePhaseEnd - fps * 0.05,
            shakePhaseEnd,
          ],
          [0, 1, 1, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const rotationAngle =
          shakeEnvelope * Math.sin((frame - shakePhaseStart) * 0.8) * 3;
        const yOffset =
          shakeEnvelope * Math.cos((frame - shakePhaseStart) * 1.2) * 2;

        // 1.0s - 1.4s: Draw X Marks
        const crossIndex = sortedXIndices.indexOf(index);
        const xPhaseStart = fps * 1.0;
        const xDuration = (fps * 0.4) / Math.max(1, sortedXIndices.length);
        const myXStart = xPhaseStart + crossIndex * xDuration;

        const line1Progress =
          crossIndex !== -1
            ? interpolate(
                frame - myXStart,
                [0, xDuration / 2],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              )
            : 0;

        const line2Progress =
          crossIndex !== -1
            ? interpolate(
                frame - myXStart,
                [xDuration / 2, xDuration],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              )
            : 0;

        const xPathLength = 110;

        return (
          <div
            key={index}
            style={{
              position: "relative",
              width: "18%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transform: `scale(${Math.max(
                0,
                scale
              )}) rotate(${rotationAngle}deg) translateY(${yOffset}px)`,
              transformOrigin: "center center",
              transition: "none",
            }}
          >
            <svg
              width="100%"
              viewBox="0 0 120 70"
              style={{ overflow: "visible" }}
            >
              {/* Trailer Body */}
              <rect
                x="5"
                y="10"
                width="70"
                height="40"
                rx="3"
                fill={truckPrimaryColor}
              />
              
              {/* Truck Cab Base */}
              <path
                d="M 78 20 L 92 20 A 5 5 0 0 1 97 25 L 105 45 Q 106 48 103 50 L 78 50 Z"
                fill={truckPrimaryColor}
              />

              {/* Cab Window Cutout */}
              <path
                d="M 82 23 L 90 23 A 2 2 0 0 1 92 25 L 96 35 L 82 35 Z"
                fill={truckDetailColor}
              />

              {/* Trailer Streaks / Details */}
              <line
                x1="12"
                y1="20"
                x2="68"
                y2="20"
                stroke={truckDetailColor}
                strokeWidth="2"
                strokeLinecap="round"
                opacity={0.4}
              />
              <line
                x1="12"
                y1="30"
                x2="58"
                y2="30"
                stroke={truckDetailColor}
                strokeWidth="2"
                strokeLinecap="round"
                opacity={0.4}
              />

              {/* Hitch Connection */}
              <rect x="72" y="42" width="6" height="4" fill="#555" />

              {/* Wheels Background (Dark) & Hubcaps */}
              <circle cx="20" cy="50" r="8" fill="#111" />
              <circle cx="20" cy="50" r="3" fill={truckDetailColor} />

              <circle cx="42" cy="50" r="8" fill="#111" />
              <circle cx="42" cy="50" r="3" fill={truckDetailColor} />

              <circle cx="85" cy="50" r="8" fill="#111" />
              <circle cx="85" cy="50" r="3" fill={truckDetailColor} />

              <circle cx="100" cy="50" r="8" fill="#111" />
              <circle cx="100" cy="50" r="3" fill={truckDetailColor} />

              {/* Red X Mark Overlay */}
              {crossIndex !== -1 && (
                <g>
                  <line
                    x1="10"
                    y1="10"
                    x2="100"
                    y2="60"
                    stroke={xMarkColor}
                    strokeWidth="12"
                    strokeLinecap="round"
                    strokeDasharray={xPathLength}
                    strokeDashoffset={xPathLength * (1 - line1Progress)}
                    style={{ transition: "none" }}
                  />
                  <line
                    x1="100"
                    y1="10"
                    x2="10"
                    y2="60"
                    stroke={xMarkColor}
                    strokeWidth="12"
                    strokeLinecap="round"
                    strokeDasharray={xPathLength}
                    strokeDashoffset={xPathLength * (1 - line2Progress)}
                    style={{ transition: "none" }}
                  />
                </g>
              )}
            </svg>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default FleetCrossout;